// ── Provider colors (subset for chips) ─────────────────────────────────────────

const PROVIDER_CHIP_COLORS: Record<number, string> = {
  8:   '#E50914', // Netflix
  337: '#113CCF', // Disney+
  9:   '#00A8E0', // Prime
  350: '#555',    // Apple TV+
  1899:'#002BE7', // Max
  15:  '#3DBB3D', // Hulu
  386: '#D0A42C', // Peacock
  531: '#0064FF', // Paramount+
  283: '#F47521', // Crunchyroll
  11:  '#5C3317', // MUBI
};

// Genre list (subset shown in filter)
const FILTER_GENRES: [number, string][] = [
  [28, 'Action'], [12, 'Adventure'], [16, 'Animation'], [35, 'Comedy'],
  [80, 'Crime'], [18, 'Drama'], [14, 'Fantasy'], [27, 'Horror'],
  [9648, 'Mystery'], [10749, 'Romance'], [878, 'Sci-Fi'], [53, 'Thriller'],
  [37, 'Western'], [99, 'Documentary'],
];

// ── Component ──────────────────────────────────────────────────────────────────

export interface Props {
  filters: DiscoverFilters;
  onChange: (f: DiscoverFilters) => void;
  onClose: () => void;
}

function toggle<T>(arr: T[], val: T): T[] {
  return arr.includes(val) ? arr.filter((x) => x !== val) : [...arr, val];
}

export function FilterModal({ filters, onChange, onClose }: Props) {
  // Local pending state — only committed on Apply
  const [pending, setPending] = React.useState<DiscoverFilters>(() => ({
    genres: [...filters.genres],
    providerIds: [...filters.providerIds],
    decades: [...filters.decades],
  }));

  const totalActive = pending.genres.length + pending.providerIds.length + pending.decades.length;

  const handleReset = useCallback(() => {
    setPending({ genres: [], providerIds: [], decades: [] });
  }, []);

  const handleApply = useCallback(() => {
    onChange(pending);
    onClose();
  }, [onChange, onClose, pending]);

  const handleScrimClick = useCallback((e: React.MouseEvent) => {
    if (e.target === e.currentTarget) onClose();
  }, [onClose]);

  return ReactDOM.createPortal(
    <Scrim onClick={handleScrimClick}>
      <Panel>
        <Header>
          <HeaderTitle>
            Filter{totalActive > 0 ? ` · ${totalActive}` : ''}
          </HeaderTitle>
          <HeaderActions>
            {totalActive > 0 && (
              <ResetBtn onClick={handleReset}>
                <RotateCcw size={12} />
                Reset
              </ResetBtn>
            )}
            <CloseBtn onClick={onClose} aria-label="Close filters">
              <X size={16} />
            </CloseBtn>
          </HeaderActions>
        </Header>

        <Body>
          {/* Genres */}
          <Section>
            <SectionTitle>Genre</SectionTitle>
            <ChipGrid>
              {FILTER_GENRES.map(([id, name]) => (
                <Chip
                  key={id}
                  active={pending.genres.includes(id)}
                  onClick={() => setPending((p) => ({ ...p, genres: toggle(p.genres, id) }))}
                >
                  {pending.genres.includes(id) && <Check size={10} />}
                  {name}
                </Chip>
              ))}
            </ChipGrid>
          </Section>

          {/* Streaming platforms */}
          <Section>
            <SectionTitle>Streaming Platform</SectionTitle>
            <ChipGrid>
              {STREAMING_PROVIDERS.map((p) => {
                const color = PROVIDER_CHIP_COLORS[p.id] ?? '#888';
                const active = pending.providerIds.includes(p.id);
                return (
                  <ProviderChip
                    key={p.id}
                    active={active}
                    color={color}
                    onClick={() => setPending((prev) => ({ ...prev, providerIds: toggle(prev.providerIds, p.id) }))}
                  >
                    <ProviderDot bg={color} />
                    {p.name}
                    {active && <Check size={10} />}
                  </ProviderChip>
                );
              })}
            </ChipGrid>
          </Section>

          {/* Decades */}
          <Section>
            <SectionTitle>Era / Decade</SectionTitle>
            <ChipGrid>
              {DECADES.map((d) => (
                <Chip
                  key={d}
                  active={pending.decades.includes(d)}
                  onClick={() => setPending((p) => ({ ...p, decades: toggle(p.decades, d) }))}
                >
                  {pending.decades.includes(d) && <Check size={10} />}
                  {d}
                </Chip>
              ))}
            </ChipGrid>
          </Section>
        </Body>

        <Footer>
          <ApplyBtn hasFilters={totalActive > 0} onClick={handleApply}>
            {totalActive > 0
              ? <><Check size={15} /> Apply {totalActive} filter{totalActive !== 1 ? 's' : ''}</>
              : 'No filters active'
            }
          </ApplyBtn>
        </Footer>
      </Panel>
    </Scrim>,
    document.body,
  );
}
